# >>> STATIC
_static_environment_arg() {
    cat <<-'ARGCEOF'
	home	display the path where gems are installed
	path	display path used to search for gems
	user_gemhome	display the path where gems are installed when --user-install is given
	version	display the gem format version
	remotesources	display the remote gem servers
	platform	display the supported gem platforms
	credentials	display the path where credentials are stored
ARGCEOF
}
# <<< STATIC

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_command() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    _argc_util_comp_command
}

_choice_command_args() {
    if [[ "${#argc__positionals[@]}" -lt 2 ]]; then
        _choice_command
    else
        _argc_util_comp_subcommand 0
    fi
}

_choice_document() {
    printf '%s\n' rdoc ri
}

_choice_gem() {
    gem list --no-versions 2>/dev/null
}

_choice_gem_version() {
    if [[ -n "${argc_gem_name:-}" ]]; then
        gem list --exact --versions "$argc_gem_name" 2>/dev/null \
            | gawk -F'[()]' 'NF > 1 { n = split($2, v, ", "); for (i = 1; i <= n; i++) print v[i] }'
    fi
}

_choice_key_algorithm() {
    printf '%s\n' RSA DSA EC
}

_choice_source() {
    gem sources --list 2>/dev/null | grep -E '^[A-Za-z][A-Za-z0-9+.-]*://'
}

_choice_trust_policy() {
    printf '%s\n' NoSecurity AlmostNoSecurity LowSecurity MediumSecurity HighSecurity
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
